// Obtener el texto del mensaje (soporta varios formatos de Evo API)
const msg =
  $json.body?.data?.message?.conversation ||
  $json.body?.data?.message?.extendedTextMessage?.text ||
  $input.first().json.message.content ||
  "";

// Normalizar
const texto = msg.trim();

// Detectar mensaje inicial típico del bot
if (/ok[, ]*buscando correo/i.test(texto)) {
  return [
    {
      esCodigo: false,
      codigo: null,
      mensaje: null,
      tipo: "buscando"
    }
  ];
}

// Buscar código de 4 o 6 dígitos
const match = texto.match(/\b\d{4}\b|\b\d{6}\b/);

if (match) {
  return [
    {
      esCodigo: true,
      codigo: match[0],
      mensaje: null,
      tipo: "codigo"
    }
  ];
}

// Si no es código → lo tratamos como mensaje de error/respuesta del bot
return [
  {
    esCodigo: false,
    codigo: null,
    mensaje: texto,
    tipo: "error"
  }
];

const raw = $input.first().json.data.telefono + "@s.whatsapp.net";

const telefono = raw;
const telefonoMySQL = raw.split("@")[0];
const mensaje = $('merge a').first().json.mensaje;
const instance = $('merge a').first().json.instance;
const apikey = $('merge a').first().json.apikey;
const usuariocue = $('merge a').first().json.mensaje.split(" ")[1];

return [
  {
    telefono,
    mensaje,
    telefonoMySQL,
    instance,
    apikey,
    usuariocue,
  }
];

const input = $input.first().json;
const body = input.body || {};
const data = body.data || {};
const msg = data.message || {};
const key = data.key || {};

const fromMe = key.fromMe === true;

// server_url debe ser string, no objeto
const server_url = String(body.server_url || "").trim();

// numero base
const rawJid = String(input.numero || key.remoteJid || body.sender || "");
const numero = rawJid.split("@")[0].replace(/\D/g, "");

// tipo de mensaje
let messageType = "unknown";
if (msg.conversation) messageType = "texto";
else if (msg.extendedTextMessage) messageType = "texto";
else if (msg.audioMessage) messageType = "audio";
else if (msg.imageMessage) messageType = "imagen";
else if (msg.videoMessage) messageType = "video";
else if (msg.documentMessage) messageType = "documento";

// contenido
let content = "";
if (msg.conversation) content = msg.conversation;
else if (msg.extendedTextMessage) content = msg.extendedTextMessage.text || "";
else if (msg.imageMessage) content = msg.imageMessage.caption || "";
else if (msg.videoMessage) content = msg.videoMessage.caption || "";

// ids
const messageID = String(key.id || "");
const chatID = String(body.sender || rawJid || "");

// ignorar grupos
if (chatID.endsWith("@g.us")) {
  return [];
}

// instancia
const instanceName = String(body.instance || "").trim();

// apikey por instancia
const apikeys = {
  "bot-pagos": "68E6084D0489-44B9-909A-632E54ACDD64",
  "default": "040E38A519FF-405D-9860-D083DFE9754F"
};
const apikey = apikeys[instanceName] || apikeys.default;

// empleados
const empleados = [
  "593961778319",
  "593996464991",
  "593961412826",
  "593961702129",
  "593986740052",

  "573105948236",
  "593960523682",
  "593962159166",
  "593983237958",
];

const esEmpleado = empleados.includes(numero);
const tipo = esEmpleado ? "empleado" : "cliente";

let color = "azul";
if (instanceName === "bot-pagos") color = "verde";

return [
  {
    json: {
      canal: "whatsapp",
      canal_user_id: numero,

      content,

      instance: {
        name: instanceName,
        apikey,
        server_url,
        color
      },

      message: {
        id: messageID,
        chat_id: chatID,
        from: numero,
        type: messageType,
        content,
        fromMe
      },

      contact: {
        numero,
        tipo,
        esEmpleado
      }
    }
  }
];

// ==========================
// 1. OBTENER RESPUESTA OPENAI
// ==========================
const input = $input.first().json;

let raw =
  input?.["0"]?.content?.[0]?.text ||
  input?.content?.[0]?.text ||
  input?.message?.content ||
  input?.text ||
  "";

if (typeof raw !== "string") {
  raw = JSON.stringify(raw);
}

raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// ==========================
// 2. PARSEAR JSON
// ==========================
let parsed;
let jsonValido = true;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
  jsonValido = false;
}

// ==========================
// 3. UTILIDADES
// ==========================
const normalize = (str) => {
  if (str === null || str === undefined) return null;

  return String(str)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s.+-]/g, " ")
    .replace(/\s+/g, " ")
    .trim() || null;
};

const parseNumber = (v) => {
  if (v === null || v === undefined || v === "") return null;
  if (typeof v === "number") return Number.isFinite(v) ? v : null;

  const s = String(v)
    .replace(/[$\s]/g, "")
    .replace(/[^0-9,.-]/g, "")
    .replace(",", ".");

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const uniq = (arr) => [...new Set(arr.filter(Boolean))];
const safeArray = (v) => Array.isArray(v) ? v : [];

// ==========================
// LIMPIAR NOMBRE / EMISOR
// ==========================
const cleanPersonName = (v) => {
  let s = normalize(v);
  if (!s) return null;

  // Quita etiquetas iniciales repetidas
  s = s
    .replace(/^(de|del|desde|emisor|remitente|ordenante|origen)\s+/i, "")
    .replace(/^(a|para|beneficiario|titular|destinatario|destino)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  return s || null;
};

// ==========================
// LIMPIAR COMPROBANTE
// ==========================
const cleanReceipt = (v) => {
  if (v === null || v === undefined) return null;

  const original = String(v).trim();
  if (!original) return null;

  const compact = original
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, "");

  // Frases que NUNCA deben guardarse como número de comprobante
  const forbidden = [
    "transferenciaexitosa",
    "transferenciarealizada",
    "transferenciaaprobada",
    "pagoexitoso",
    "pagorealizado",
    "comprobantepago",
    "comprobantedepago",
    "transferencia"
  ];

  if (forbidden.includes(compact)) return null;

  // Prioridad: números de 5+ dígitos
  const digitMatches = original.match(/\d{5,}/g);
  if (digitMatches?.length) {
    return digitMatches.sort((a, b) => b.length - a.length)[0];
  }

  // Permitir códigos alfanuméricos solo si tienen números y longitud razonable
  const alnum = original.replace(/[^a-zA-Z0-9]/g, "");

  if (
    alnum.length >= 6 &&
    /\d/.test(alnum) &&
    !/^[a-zA-Z]+$/.test(alnum)
  ) {
    return alnum;
  }

  return null;
};

// Busca comprobantes válidos en varios campos por si la IA lo puso en otro lado
const findReceiptCandidate = (items, parsed) => {
  const candidates = [];

  for (const c of items) {
    candidates.push(c?.comprobante);
    candidates.push(c?.referencia);
    candidates.push(c?.transaccion);
    candidates.push(c?.codigo_transaccion);
    candidates.push(c?.numero_comprobante);
  }

  candidates.push(parsed.comprobante);
  candidates.push(parsed.referencia);
  candidates.push(parsed.transaccion);
  candidates.push(parsed.codigo_transaccion);
  candidates.push(parsed.qr_contenido);

  for (const candidate of candidates) {
    const cleaned = cleanReceipt(candidate);
    if (cleaned) return cleaned;
  }

  return null;
};

// ==========================
// 4. DETECTAR TIPO
// ==========================
const esComprobante = parsed.es_comprobante === true;

// ==========================
// 5. SI ES COMPROBANTE
// ==========================
if (esComprobante) {
  let comprobantes = safeArray(parsed.comprobantes);

  if (!comprobantes.length) {
    comprobantes = [
      {
        comprobante: parsed.comprobante ?? null,
        monto: parsed.monto ?? null,
        banco: parsed.banco ?? parsed.banco_principal ?? null,
        fecha: parsed.fecha ?? null,
        titular: parsed.titular ?? null,
        emisor: parsed.emisor ?? null,
      }
    ];
  }

  const comprobantesNorm = comprobantes.map((c) => ({
    comprobante: cleanReceipt(c?.comprobante),
    monto: parseNumber(c?.monto),
    banco: normalize(c?.banco),
    fecha: c?.fecha || null,
    titular: cleanPersonName(c?.titular),
    emisor: cleanPersonName(c?.emisor),
  }));

  const totalComprobantes =
    parseNumber(parsed.total_comprobantes) ?? comprobantesNorm.length;

  const montoTotalDetectado =
    parseNumber(parsed.monto_total_detectado) ??
    comprobantesNorm.reduce((sum, c) => sum + (c.monto ?? 0), 0);

  const bancoPrincipal =
    normalize(parsed.banco_principal) ||
    comprobantesNorm.find((c) => c.banco)?.banco ||
    normalize(parsed.banco) ||
    null;

  const fechasDetectadas = uniq([
    ...safeArray(parsed.fechas_detectadas),
    ...comprobantesNorm.map((c) => c.fecha),
    parsed.fecha || null
  ]);

  // Comprobante principal: el de mayor monto
  const conMonto = comprobantesNorm.filter((c) => c.monto !== null);

  const principal = conMonto.length
    ? conMonto.sort((a, b) => (b.monto ?? 0) - (a.monto ?? 0))[0]
    : comprobantesNorm[0] || {};

  // Si el comprobante principal no tiene número válido, buscar en todos los campos
  const comprobanteFinal =
    principal.comprobante ||
    findReceiptCandidate(comprobantes, parsed);

  const emisorFinal =
    principal.emisor ||
    cleanPersonName(parsed.emisor) ||
    null;

  const titularFinal =
    principal.titular ||
    cleanPersonName(parsed.titular) ||
    null;

  const errores = [];

  if (!jsonValido) errores.push("JSON IA inválido");
  if (!comprobanteFinal) errores.push("Número de comprobante no detectado");
  if (!montoTotalDetectado) errores.push("Monto no detectado");
  if (!bancoPrincipal) errores.push("Banco no detectado");
  if (!emisorFinal) errores.push("Emisor no detectado");

  const listoParaCargar = errores.length === 0;

  return [
    {
      json: {
        tipo: "comprobante",
        es_comprobante: true,
        listo_para_cargar: listoParaCargar,
        errores: errores.join(", "),

        data: {
          comprobante: comprobanteFinal,
          monto: montoTotalDetectado ?? null,
          monto_total_detectado: montoTotalDetectado ?? null,
          total_comprobantes: totalComprobantes ?? 1,

          banco: bancoPrincipal,
          bancos_detectados: uniq(comprobantesNorm.map((c) => c.banco)),

          fecha: principal.fecha ?? parsed.fecha ?? null,
          fechas_detectadas: fechasDetectadas,

          titular: titularFinal,
          emisor: emisorFinal,

          comprobantes: comprobantesNorm
        },

        validacion: {
          legible: parsed.legible ?? null,
          borroso: parsed.borroso ?? null,
          editado: parsed.editado ?? null,
          realista: parsed.realista ?? null,
          confianza: parseNumber(parsed.confianza),
        },

        qr: {
          detectado: parsed.qr_detectado ?? false,
          valido: parsed.qr_valido_visualmente ?? false,
          contenido: parsed.qr_contenido ?? null,
        },

        raw
      }
    }
  ];
}

// ==========================
// 6. SI NO ES COMPROBANTE
// ==========================
const descripcion = parsed.descripcion || "No se pudo describir";

return [
  {
    json: {
      tipo: "imagen",
      es_comprobante: false,
      listo_para_cargar: false,
      content: "<imagen>" + descripcion + "<imagen>",
      tipo_imagen: parsed.tipo_imagen || "desconocido",
      confianza: parseNumber(parsed.confianza),
      raw
    }
  }
];
